from pwn import *
import re

def parse_r2_script(filename):
    with open(filename, 'r') as f:
        script = f.read()

    # Extract memory writes
    wx_cmds = re.findall(r'wx ([0-9a-f]+)', script)
    print("=== Memory Writes ===")
    for hex_data in wx_cmds:
        try:
            ascii_data = bytes.fromhex(hex_data).decode('ascii', errors='ignore')
            if any(c.isalnum() for c in ascii_data):
                print(f"Hex: {hex_data}")
                print(f"ASCII: {ascii_data}\n")
        except:
            continue

    # Extract temp file operations
    tmp_ops = re.findall(r'/tmp/([A-Z0-9]+)', script)
    print("\n=== Temporary Files ===")
    for tmp in sorted(set(tmp_ops)):
        print(tmp)

    # Extract commands and data flow
    cmds = script.split('\n')
    print("\n=== Data Flow Analysis ===")
    for cmd in cmds:
        if '>' in cmd or ';.' in cmd:
            print(cmd.strip())

parse_r2_script('ctf_files/welcome2.r2')

#!/usr/bin/env python3
from pwn import *
import re
import os

def decode_hex_block(hex_str):
    try:
        # Remove spaces and convert to bytes
        hex_bytes = bytes.fromhex(hex_str.replace(' ', ''))
        return hex_bytes
    except:
        return None

def parse_script(script_path):
    with open(script_path) as f:
        script = f.read()

    # Extract the initial memory block
    memory_block = ''
    for line in script.splitlines():
        if line.startswith('# 0x'):
            hex_data = line[51:].split('  ')[0].replace(' ', '')
            memory_block += hex_data

    # Parse memory operations
    memory_ops = []
    for line in script.splitlines():
        if line.startswith('wx '):
            hex_data = line[3:].split('@')[0].strip()
            location = line.split('@')[1].strip() if '@' in line else ''
            memory_ops.append(('write', hex_data, location))

    # Parse hit points
    hit_points = {}
    for line in script.splitlines():
        if line.startswith('f hit'):
            parts = line.split('=')
            if len(parts) == 2:
                hit_num = int(parts[0].replace('f hit', '').strip())
                hit_addr = int(parts[1].strip())
                hit_points[hit_num] = hit_addr

    print("Initial memory block:")
    if memory_block:
        mem_bytes = decode_hex_block(memory_block)
        if mem_bytes:
            print(hexdump(mem_bytes))
            try:
                print("ASCII:", mem_bytes.decode('ascii', errors='replace'))
            except:
                pass

    print("\nMemory Operations:", len(memory_ops))
    for i, (op, data, loc) in enumerate(memory_ops[:5]):
        print(f"{i}: {op} {data[:20]}... @ {loc}")

    print(f"\nHit Points: {len(hit_points)}")
    sorted_hits = sorted(hit_points.items(), key=lambda x: x[0])
    for hit_num, addr in sorted_hits[:5]:
        print(f"hit{hit_num} = {addr}")

    # Analyze the data for patterns
    all_data = ''
    for _, data, _ in memory_ops:
        all_data += data

    print("\nAnalyzing hex data for patterns...")
    try:
        data_bytes = bytes.fromhex(all_data)
        # Look for printable strings
        strings = re.findall(rb'[A-Za-z0-9_}{]+', data_bytes)
        for s in strings:
            try:
                decoded = s.decode('ascii')
                if len(decoded) > 4:  # Only show strings of reasonable length
                    print(f"Found string: {decoded}")
                    # Check for flag pattern
                    if 'flag{' in decoded or '}' in decoded:
                        print(f"Possible flag component: {decoded}")
            except:
                pass
    except:
        print("Error decoding hex data")

if __name__ == '__main__':
    parse_script('ctf_files/welcome2.r2')

#!/usr/bin/env python3
from pwn import *
import re

def decode_hex_block(hex_str):
    try:
        hex_bytes = bytes.fromhex(hex_str.replace(' ', ''))
        return hex_bytes
    except:
        return None

def decode_commands(hex_str):
    try:
        hex_bytes = bytes.fromhex(hex_str.replace(' ', ''))
        return hex_bytes.decode('ascii', errors='replace')
    except:
        return None

def parse_script(script_path):
    with open(script_path) as f:
        script = f.read()

    # Parse memory writes and track file operations
    file_ops = []
    current_data = []

    for line in script.splitlines():
        if line.startswith('wx '):
            hex_data = line[3:].split('@')[0].strip()
            # Try to decode the hex data
            decoded = decode_commands(hex_data)
            if decoded:
                # Look for file operations
                if '/tmp/' in decoded:
                    file_ops.append(decoded)
                current_data.append(decoded)

    print("Analyzing file operations...")
    for i, op in enumerate(file_ops):
        print(f"\nOperation {i}:")
        print(op)

    print("\nAnalyzing data flow...")
    # Track data movement between memory locations
    for data in current_data:
        if 'loc.flag' in data or 'loc.hash' in data:
            print(f"\nMemory Operation: {data}")

    # Look for flag format patterns
    print("\nLooking for flag patterns...")
    flag_pattern = re.compile(r'flag{[^}]*}')
    all_data = ' '.join(current_data)
    matches = flag_pattern.findall(all_data)
    for match in matches:
        print(f"Found possible flag: {match}")

if __name__ == '__main__':
    parse_script('ctf_files/welcome2.r2')

#!/usr/bin/env python3
from pwn import *
import re

def decode_hex_command(hex_str):
    try:
        # Remove any spaces and decode
        hex_bytes = bytes.fromhex(hex_str.strip())
        return hex_bytes.decode('ascii', errors='replace')
    except:
        return None

def analyze_script(script_path):
    with open(script_path) as f:
        script = f.read()

    # Extract and decode hex commands
    hex_commands = []

    for line in script.splitlines():
        if line.startswith('wx '):
            hex_data = line[3:].split(';')[0].strip()
            decoded = decode_hex_command(hex_data)
            if decoded:
                hex_commands.append(decoded)

    # Analyze commands for patterns
    print("Analyzing decoded commands:")
    full_command = ''
    for cmd in hex_commands:
        full_command += cmd

    # Split into individual operations
    operations = full_command.split('\x00')

    print("\nExtracted Operations:")
    for op in operations:
        if op.strip():
            print(f"- {op}")

    # Look for specific patterns
    print("\nAnalyzing memory operations:")
    for op in operations:
        if 'loc.flag' in op or 'loc.hash' in op:
            print(f"Memory op: {op}")

    # Look for file operations
    print("\nAnalyzing file operations:")
    for op in operations:
        if '/tmp/' in op:
            print(f"File op: {op}")

    # Try to reconstruct the data flow
    print("\nReconstructing data flow:")
    # Track memory to file operations
    memory_ops = {
        'flag': [],
        'hash': []
    }

    for op in operations:
        if 'loc.flag' in op:
            memory_ops['flag'].append(op)
        if 'loc.hash' in op:
            memory_ops['hash'].append(op)

    print("\nFlag operations sequence:")
    for op in memory_ops['flag']:
        print(f"- {op}")

    print("\nHash operations sequence:")
    for op in memory_ops['hash']:
        print(f"- {op}")

if __name__ == '__main__':
    analyze_script('ctf_files/welcome2.r2')
